import Foundation
import UIKit

/// Build92/45 hardware-triggered real Swift-vs-original Python source tapes.
/// The 12-stage reference data is generated by actual upstream source
/// *before* XcodeGen and retained as an app-bundled folder reference.
/// A successful CI arm64 build is not device execution or scientific proof.
enum Build92DeviceSourceStageDiagnostic {
    enum Failure:LocalizedError {
        case invalid(String)
        var errorDescription:String? {
            if case let .invalid(message)=self{return message}
            return nil
        }
    }
    static func evaluate()throws->String {
        guard let manifest=Bundle.main.url(
            forResource:"manifest",withExtension:"json",
            subdirectory:"generated-physical-v1.8.22"
        ) else {
            throw Failure.invalid(
                "Build92 原版 Python 12 阶段整图参考未打包，" +
                "不能在真实设备上声称已对照"
            )
        }
        let location=manifest.deletingLastPathComponent()
        guard FileManager.default.fileExists(
            atPath:location.appendingPathComponent(
                "kodak_grain_micro_yvv.grainPrinted.f64le"
            ).path
        ) else {
            throw Failure.invalid(
                "Build92 原版活跃 Numba 颗粒/相纸参考缺失；" +
                "真实整帧验证不能静默跳过"
            )
        }
        try SourcePhysicalImageParity.evaluate(fixtures:location)
        let version=UIDevice.current.systemVersion
        #if targetEnvironment(simulator)
        let hardware="iOS Simulator（不能认证真实 iPhone）"
        #else
        let hardware="真实 iPhone/iOS"
        #endif
        let target=version=="16.5.1"
        return "原版 Python→Swift 整帧阶段数值：本机全部 " +
            "SourcePhysicalImageParity 严格阈值测试通过；" +
            "4 组参考图、12 个 Python 测试阶段（含受控单线程" +
            " NumPy／Numba 颗粒），真实光学输出无需快速 LUT。" +
            " 环境：\(hardware) \(version)；" +
            (target
               ? "系统版本匹配 iOS 16.5.1。"
               : "系统非 iOS16.5.1，不能计入指定系统版本真机认证。") +
            " 未覆盖 RAW/高位深入口、未播种多线程随机/13MP 实际内存。"
    }
}
